import functools
import time


def retry(times, exceptions=(Exception,), delay=0.0, backoff=2.0, sleep=time.sleep):
    """Retry the decorated function on the given exceptions.

    The function is called at most ``times`` times. Between failed attempts it
    waits ``delay * backoff ** (attempt - 1)`` seconds via ``sleep``. The last
    failure is re-raised. ``wrapper.last_attempts`` holds the call count of the
    most recent invocation.
    """
    if times < 1:
        raise ValueError(f"times must be at least 1, got {times!r}")
    if delay < 0:
        raise ValueError(f"delay must be non-negative, got {delay!r}")
    if backoff < 1:
        raise ValueError(f"backoff must be at least 1, got {backoff!r}")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            wrapper.last_attempts = 0
            for attempt in range(1, times + 1):
                wrapper.last_attempts = attempt
                try:
                    return func(*args, **kwargs)
                except exceptions:
                    if attempt == times:
                        raise
                    if delay:
                        sleep(delay * backoff ** (attempt - 1))

        wrapper.last_attempts = 0
        return wrapper

    return decorator

